bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 60
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import {readFileSync} from 'node:fs';
const p=readFileSync('/opt/videobot/src/telegram/paidListingPublisher.mjs','utf8');
const m=readFileSync('/opt/videobot/src/telegram/paidMedia.mjs','utf8');
if(!p.includes('sendPaidMedia'))process.exitCode=61;
else if(!m.includes('star_count:priceStars'))process.exitCode=62;
else if(p.includes('paidResult?.paid_media?.star_count'))process.exitCode=71;
else if(p.includes('paidResult.paid_media?.star_count'))process.exitCode=72;
else if(p.includes('paidResult.paid_media.star_count'))process.exitCode=73;
else if(p.includes('paidResult?.paid_media'))process.exitCode=74;
else if(p.includes('paidResult.paid_media'))process.exitCode=75;
else process.exitCode=76;
JS
